from collections import Counter

def train_bpe(corpus, num_merges=10):
    # 初始化: 每个词拆成字符
    word_freq = Counter(corpus.split())
    splits = {w: list(w) for w in word_freq}

    merges = []
    for _ in range(num_merges):
        # 统计相邻字符对频率
        pairs = Counter()
        for w, freq in word_freq.items():
            split = splits[w]
            for i in range(len(split) - 1):
                pairs[(split[i], split[i+1])] += freq
        if not pairs:
            break
        # 合并最高频对
        best = pairs.most_common(1)[0][0]
        merges.append(best)
        # 更新 splits
        for w in splits:
            split = splits[w]
            i = 0
            while i < len(split) - 1:
                if (split[i], split[i+1]) == best:
                    split[i:i+2] = [''.join(best)]
                else:
                    i += 1
    return merges

corpus = 'low low low low low lower lower newest newest newest newest newest newest widest widest'
print(train_bpe(corpus, 5))

